// The QA group: the Slack user group's members (needs a paid Slack plan), or
// the member IDs listed in Settings. Reactions from anyone else are ignored.
const settings = $('Settings').first().json;
const group = $input.first().json;
const fromGroup = group.ok && Array.isArray(group.users) ? group.users : [];
const fromList = String(settings.qa_member_ids || '').split(',').map((s) => s.trim()).filter(Boolean);
return [{ json: { members: [...new Set([...fromGroup, ...fromList])] } }];

// 🙈 decisions waiting for their reason: look for the member's reply.
const list = (v) => (Array.isArray(v) ? v : JSON.parse(v || '[]'));
return list($('Load messages').first().json.messages)
  .filter((m) => m.decision && m.decision.state === 'waiting-for-reason' && m.decision.prompt_ts)
  .map((m) => ({ json: { ...m, channel_id: m.channel, thread: m.thread_ts || m.ts } }));

// The member's first reply in the thread after the prompt is the reason.
const waiting = $('Waiting for a reason').all();
return $input.all().flatMap((page, i) => {
  const m = waiting[i].json;
  const reply = (page.json.messages ?? []).find((r) => r.user === m.decision.actor_id && Number(r.ts) > Number(m.decision.prompt_ts)
    && typeof r.text === 'string' && r.text.trim());
  if (!reply) return [];
  const reason = reply.text.trim().replace(/\s+/g, ' ').slice(0, 300);
  return [{ json: { ...m, reason, reply_ts: reply.ts } }];
});

parameters.query:
WITH saved AS (
  UPDATE audit.reaction_decisions SET state = 'handled', reason = $2, handled_at = now()
  WHERE id = $1::bigint AND state = 'waiting-for-reason'
  RETURNING id
)
SELECT (SELECT id FROM saved) AS id;

