// S4 for 🙈 once its reason is recorded.
const found = $('Reasons found').all();
return $input.all().flatMap((row, i) => {
  if (!row.json.id) return [];
  const m = found[i].json;
  return [{ json: { kind: '', header: `Ignored by ${m.decision.actor_name}`,
    body: `<@${m.decision.actor_id}> marked this failure 🙈 Ignore. Reason: "${m.reason}". The gate is unchanged.`,
    todo: '', todo_label: '', links: [], legend: '↩️ within 24 h to undo', thread_ts: m.thread },
    pairedItem: i }];
});

const failed = $input.all().filter((p) => !p.json.posted && !p.json.preview);
if (failed.length) throw new Error(`ignore confirmation not posted: ${failed[0].json.error}`);
return $('Reasons found').all().map((m) => ({ json: {
  actor: m.json.decision.actor_email, actor_type: 'human', action: 'decision-ignore',
  target: `${m.json.test_id || m.json.ticket}: ${m.json.reason}`.slice(0, 300), link: '' } }));

// Messages with no live decision yet: read their reactions.
const list = (v) => (Array.isArray(v) ? v : JSON.parse(v || '[]'));
return list($('Load messages').first().json.messages).filter((m) => !m.decision).map((m) => ({ json: m }));

// The first reaction Slack lists that is valid for the message kind and was
// added by a QA group member (EXPERIENCE.md, reaction legend). Other emoji,
// reactions from anyone else, and any later reactions are ignored; ↩️ is
// handled by the undo step (Story 6.8).
// Slack names copied from contracts/vocabulary.json (reactions[*].slack_names);
// scripts/tests/test_n8n_workflows.py checks the copy.
const REACTIONS = {"bug": {"names": ["lady_beetle", "ladybug", "beetle"], "valid_on": ["failure"]}, "flaky": {"names": ["repeat"], "valid_on": ["failure"]}, "environment": {"names": ["lightning", "lightning_cloud", "cloud_with_lightning"], "valid_on": ["failure"]}, "ignore": {"names": ["see_no_evil"], "valid_on": ["failure"]}, "approve": {"names": ["white_check_mark"], "valid_on": ["questions"]}, "undo": {"names": ["leftwards_arrow_with_hook"], "valid_on": ["failure", "questions"]}};
const members = new Set($('QA members').first().json.members);
const messages = $('To check').all();
const actionOf = (name, kind) => Object.entries(REACTIONS)
  .find(([action, r]) => action !== 'undo' && r.valid_on.includes(kind) && r.names.includes(name.split('::')[0]))?.[0];
return $input.all().flatMap((page, i) => {
  const m = messages[i].json;
  for (const reaction of page.json.message?.reactions ?? []) {
    const action = actionOf(reaction.name ?? '', m.kind);
    const user = action ? (reaction.users ?? []).find((u) => members.has(u)) : undefined;
    if (user) return [{ json: { ...m, action, actor_id: user } }];
  }
  return [];
});

// Who reacted (email and name from their Slack profile).
const found = $('First valid reaction').all();
return $input.all().flatMap((user, i) => {
  const m = found[i].json;
  const profile = user.json.user?.profile ?? {};
  const email = profile.email || `${m.actor_id}@slack.invalid`;
  const name = profile.display_name || profile.real_name || user.json.user?.name || m.actor_id;
  return [{ json: { ...m, actor_email: email, actor_name: name,
    state: m.action === 'ignore' ? 'waiting-for-reason' : 'handled' } }];
});

// S4 (Environment) and S5 (Ignore reason prompt), in the message's thread.
// Only decisions just recorded get a reply (none twice).
const decisions = $('Slack-only decisions').all();
return $input.all().flatMap((row, i) => {
  if (!row.json.id) return [];
  const d = decisions[i].json;
  const base = { decision_id: row.json.id, kind: '', todo: '', todo_label: '', links: [], thread_ts: d.thread_ts || d.ts, action: d.action };
  if (d.action === 'environment') {
    return [{ json: { ...base, header: `Marked Environment by ${d.actor_name}`,
      body: `<@${d.actor_id}> marked this failure 🌩️ Environment. The gate is unchanged. This will show in the daily update.`,
      legend: '↩️ within 24 h to undo' } }];
  }
  return [{ json: { ...base, header: 'A reason is needed for 🙈 Ignore',
    body: `<@${d.actor_id}>, to record 🙈 Ignore, reply in this thread with a short reason. Nothing is recorded until then.`, legend: '' } }];
});

// Slack didn't take a reply: fail (W0 alerts). Otherwise remember the prompt's
// ts for 🙈, so the reason reply can be found.
const replies = $('Replies').all();
const posts = $input.all();
const failed = posts.filter((p) => !p.json.posted && !p.json.preview);
if (failed.length) throw new Error(`reaction reply not posted: ${failed[0].json.error}`);
return posts.map((p, i) => ({ json: { decision_id: replies[i].json.decision_id, action: replies[i].json.action, prompt_ts: p.json.ts ?? '' } }));

// Audit with the member's email as the actor (FR-26).
return $('Slack-only decisions').all().filter((d) => d.json.action === 'environment').map((d) => ({ json: {
  actor: d.json.actor_email, actor_type: 'human', action: 'decision-environment',
  target: d.json.test_id || d.json.ticket, link: d.json.nightly_run_id ? `https://github.com/${$('Settings').first().json.repo}/actions/runs/${d.json.nightly_run_id}` : '' } }));

// 🐞 Bug, 🔁 Flaky and ✅ Approve write to Jira: through the gate (a Jira write, AR-11).
// A reaction the gate held back is asked about again after its wait.
const now = Date.now();
return $input.all()
  .filter((d) => ['bug', 'flaky', 'approve'].includes(d.json.action))
  .filter((d) => !d.json.jira_wait_until || Date.parse(d.json.jira_wait_until) <= now)
  .map((d) => ({ json: { ...d.json, action_kind: d.json.action,
    gate: { action: 'jira-write', workflow: '', target: `reaction-${d.json.map_id}`, payload: { map_id: d.json.map_id, reaction: d.json.action } } } }));

// A 🔁 that created its owner ticket: queue the quarantine request. The queue
// step below sends it through the gate (the quarantine cap) and starts the
// workflow, so a failed start or a reached cap just waits and is retried.
const done = $('Jira results').all();
return $('Record Jira decision').all().flatMap((row, i) => (row.json.id && done[i].json.action === 'flaky' && !done[i].json.stop
  ? [{ json: done[i].json }] : []));

// Each Jira action with its result, in order: bugs, flaky, then approvals. A
// 🔁 that stopped (owner missing, already quarantined) created nothing.
const pair = (from, results) => ($(from).isExecuted ? $(from).all().map((d, i) => ({ ...d.json, ...$(results).all()[i].json })) : []);
return [...pair('Bugs', 'File bug'), ...pair('Flakies', 'Flaky'), ...pair('Approvals', 'Send questions')].map((d) => ({ json: d }));

// S4 after a Jira action (EXPERIENCE.md M4), only for decisions just recorded.
const BOT = 'Filed via QA bot';  // contracts/vocabulary.json bot_label.jira
const done = $('Jira results').all();
return $input.all().flatMap((row, i) => {
  if (!row.json.id) return [];
  const d = done[i].json;
  const who = `<@${d.actor_id}>`;
  const base = { decision_id: row.json.id, action: d.action, kind: '', todo: '', todo_label: '', thread_ts: d.thread_ts || d.ts,
    links: [{ label: `Jira ${d.jira_key}`, url: d.url }], legend: '↩️ within 24 h to undo' };
  if (d.action === 'flaky' && d.stop) {
    const why = d.stop === 'owner-missing'
      ? `Nothing was created: the flow \`${d.flow_id || 'unknown'}\` has no owner in the flow inventory. QA lead to add it to the inventory, then undo ↩️ and react 🔁 again.`
      : 'Nothing was created: this test is already in the quarantine list.';
    return [{ json: { ...base, header: `Flaky not recorded`, body: `${who}: ${why}`, links: [], legend: '' } }];
  }
  if (d.action === 'flaky') {
    return [{ json: { ...base, header: `Quarantine requested by ${d.actor_name}`,
      body: `Quarantine requested by ${who}. Owner ticket ${d.jira_key} created.\nThe test keeps gating until QA merges the quarantine PR.` } }];
  }
  if (d.action === 'bug') {
    return [{ json: { ...base, header: `Bug ${d.jira_key} filed by ${d.actor_name}`, body: d.reporter_ok
      ? `Bug ${d.jira_key} filed by ${who}. Labelled "${BOT}".`
      : `Bug ${d.jira_key} filed by ${who}. Jira didn't accept you as Reporter, so a "Filed by ${d.actor_name}" comment was added.` } }];
  }
  return [{ json: { ...base, header: `Questions added to ${d.jira_key}`, body: `Questions added to ${d.jira_key} as a comment naming ${who}.` } }];
});

const failed = $input.all().filter((p) => !p.json.posted && !p.json.preview);
if (failed.length) throw new Error(`Jira confirmation not posted: ${failed[0].json.error}`);
return $('Jira results').all().map((d) => ({ json: {
  actor: d.json.actor_email, actor_type: 'human', action: `decision-${d.json.action}${d.json.stop ? `-${d.json.stop}` : ''}`,
  target: d.json.action === 'approve' ? `${d.json.jira_key} questions` : `${d.json.jira_key || 'no ticket'} for ${d.json.test_id}`,
  link: d.json.url || '' } }));

const due = $('Due quarantines').all().filter((q) => q.json.jira_key);
return $input.all().flatMap((answer, i) => (answer.json.allowed === true ? [{ json: { ...due[i].json,
  payload: typeof due[i].json.payload === 'string' ? JSON.parse(due[i].json.payload) : due[i].json.payload } }] : []));

return $('Allowed quarantines').all().map((q) => ({ json: { actor: 'n8n:w3b-reactions', actor_type: 'n8n',
  action: 'dispatch-quarantine', target: `${q.json.jira_key} ${q.json.payload.quarantine_request.test_id}`.slice(0, 300),
  link: `https://github.com/${$('Settings').first().json.repo}/actions/workflows/quarantine.yml` } }));
